t.script:
                const reqId = ;
                const accessToken = '';
                const isSigned = '' === 'signed';
                const origPdfUrl = accessToken 
                    ? '/dms/signature/' + reqId + '/' + accessToken + '/pdf'
                    : '/dms/signature/' + reqId + '/pdf';

                const itemsData = [

                    {
                        id: ,
                        type: '',
                        page: ,
                        x: ,
                        y: ,
                        width: ,
                        height: ,
                        state: '',
                        valueText: ``,
                        valueBool: !!,
                        valueImage: ``,
                        radioGroupName: ``,
                        radioOptionValue: ``,
                        placeholder: ``,
                        readonly: !!,
                        mandatory: !!,
                        options: ``,
                        alignment: '',
                    },

                ];

                let answers = {};
                let currentItem = null;
                let currentFieldDiv = null;
                let signaturePad = null;

                const SIGN_TYPES = ['signature', 'initial', 'initials', 'stamp'];
                const TEXT_TYPES = ['text', 'name', 'email', 'phone', 'company', 'date'];
                const BOOL_TYPES = ['checkbox', 'radio', 'strikethrough'];
                const SVG_NS = 'http://www.w3.org/2000/svg';

                function radioGroupOf(item) {
                    return item.radioGroupName || ('radio_' + item.id);
                }

                function radioSiblings(item) {
                    const group = radioGroupOf(item);
                    return itemsData.filter(i => i.type === 'radio' && radioGroupOf(i) === group);
                }

                function splitOptions(options) {
                    if (!options) return [];
                    const separator = options.indexOf('\n') >= 0 ? '\n' : ',';
                    return options.split(separator).map(o => o.trim()).filter(Boolean);
                }

                // Is the item answered? A radio counts as answered once one option of its group is chosen.
                function isDone(item) {
                    if (item.type === 'radio') {
                        return radioSiblings(item).some(i => (answers[i.id] || {}).value_bool);
                    }
                    const answer = answers[item.id] || {};
                    if (BOOL_TYPES.includes(item.type)) return !!answer.value_bool;
                    if (SIGN_TYPES.includes(item.type)) return !!answer.value_image;
                    return !!String(answer.value_text || '').trim();
                }

                // Fields the signer must fill, radio groups counted once
                function requiredItems() {
                    const seenGroups = new Set();
                    return itemsData.filter(item => {
                        if (!item.mandatory || item.readonly) return false;
                        if (item.type === 'radio') {
                            const group = radioGroupOf(item);
                            if (seenGroups.has(group)) return false;
                            seenGroups.add(group);
                        }
                        return true;
                    });
                }

                // Values already known (auto-completed fields, choices) are part of the answers
                itemsData.forEach(item => {
                    if (BOOL_TYPES.includes(item.type)) {
                        if (item.type !== 'strikethrough' || item.valueBool) {
                            answers[item.id] = { value_bool: item.valueBool };
                        }
                    } else if (SIGN_TYPES.includes(item.type)) {
                        if (item.valueImage) answers[item.id] = { value_image: item.valueImage };
                    } else if (item.valueText) {
                        answers[item.id] = { value_text: item.valueText };
                    }
                });

                const viewer = document.getElementById('pdf-viewer');
                viewer.innerHTML = '


Loading document preview…
Please wait while the PDF is preparing.';

                if (window.pdfjsLib) {
                    try {
                        pdfjsLib.GlobalWorkerOptions.workerSrc = 'https://cdnjs.cloudflare.com/ajax/libs/pdf.js/2.16.105/pdf.worker.min.js';
                    } catch (_) {}
                }

                const scale = 1.4;

                pdfjsLib.getDocument({ url: origPdfUrl, withCredentials: true }).promise.then(function(pdfDoc) {
                    const spinner = document.getElementById('pdf-loading-spinner');
                    if (spinner) spinner.remove();

                    const pages = [];
                    for (let num = 1; num <= pdfDoc.numPages; num++) pages.push(num);
                    pages.reduce((p, num) => p.then(() => renderPage(pdfDoc, num)), Promise.resolve())
                        .then(() => updateProgress());
                }).catch(err => {
                    viewer.innerHTML = `



⚠️

Unable to Preview PDF

${err.message || 'The document could not be loaded. Please verify your connection or try refreshing.'}
                            Retry

                    `;
                });

                function renderPage(pdfDoc, num) {
                    return pdfDoc.getPage(num).then(function(page) {
                        const viewport = page.getViewport({ scale });
                        const wrap = document.createElement('div');
                        wrap.className = 'pdf-page-wrap';
                        wrap.style.width = viewport.width + 'px';
                        wrap.style.height = viewport.height + 'px';

                        const dpr = window.devicePixelRatio || 1;
                        const canvas = document.createElement('canvas');
                        canvas.width = Math.floor(viewport.width * dpr);
                        canvas.height = Math.floor(viewport.height * dpr);
                        canvas.style.width = viewport.width + 'px';
                        canvas.style.height = viewport.height + 'px';
                        wrap.appendChild(canvas);
                        viewer.appendChild(wrap);

                        const ctx = canvas.getContext('2d');
                        const xform = dpr !== 1 ? [dpr, 0, 0, dpr, 0, 0] : null;
                        return page.render({ canvasContext: ctx, transform: xform, viewport }).promise.then(() => {
                            if (!isSigned) {
                                itemsData.forEach(item => { if (item.page === num) renderField(item, wrap, viewport); });
                            }
                        });
                    });
                }

                function svgNode(tag, attrs) {
                    const node = document.createElementNS(SVG_NS, tag);
                    Object.entries(attrs).forEach(([name, value]) => node.setAttribute(name, value));
                    return node;
                }

                function choiceIcon(type, checked) {
                    const svg = svgNode('svg', { viewBox: '0 0 24 24', class: 'choice-icon', fill: 'none', stroke: '#111', 'stroke-width': '2' });
                    if (type === 'radio') {
                        svg.appendChild(svgNode('circle', { cx: 12, cy: 12, r: 9 }));
                        if (checked) svg.appendChild(svgNode('circle', { cx: 12, cy: 12, r: 4.5, fill: '#111', stroke: 'none' }));
                    } else {
                        svg.appendChild(svgNode('rect', { x: 3, y: 3, width: 18, height: 18, rx: 2 }));
                        if (checked) {
                            svg.appendChild(svgNode('polyline', {
                                points: '7 12.5 10.5 16 17 8.5', 'stroke-width': '2.5', 'stroke-linecap': 'round', 'stroke-linejoin': 'round',
                            }));
                        }
                    }
                    return svg;
                }

                function renderChoice(item, fd) {
                    fd.innerHTML = '';
                    fd.appendChild(choiceIcon(item.type, !!(answers[item.id] || {}).value_bool));
                }

                function renderField(item, container, viewport) {
                    const fd = document.createElement('div');
                    fd.className = 'sign-field';
                    fd.id = 'sign-field-' + item.id;

                    // Coordinates are stored as pure ratios (0.0–1.0) relative to page dimensions.
                    fd.style.left = (item.x * viewport.width) + 'px';
                    fd.style.top = (item.y * viewport.height) + 'px';
                    fd.style.width = (item.width * viewport.width) + 'px';
                    fd.style.height = (item.height * viewport.height) + 'px';

                    const boxHeight = item.height * viewport.height;
                    const fontSize = Math.max(10, Math.min(boxHeight * 0.6, 18)) + 'px';
                    if (item.readonly) fd.classList.add('readonly');
                    const textAlign = item.alignment || 'left';

                    if (TEXT_TYPES.includes(item.type)) {
                        const inp = document.createElement('input');
                        inp.type = item.type === 'date' ? 'date' : (item.type === 'email' ? 'email' : (item.type === 'phone' ? 'tel' : 'text'));
                        inp.placeholder = item.placeholder || item.type;
                        inp.value = item.valueText || '';
                        inp.style.fontSize = fontSize;
                        inp.style.textAlign = textAlign;
                        if (item.readonly) inp.disabled = true;
                        inp.oninput = e => setAnswer(item, 'value_text', e.target.value);
                        fd.appendChild(inp);
                    } else if (item.type === 'selection') {
                        const sel = document.createElement('select');
                        const blank = document.createElement('option');
                        blank.value = '';
                        blank.textContent = item.placeholder || 'Select...';
                        sel.appendChild(blank);
                        splitOptions(item.options).forEach(o => {
                            const opt = document.createElement('option');
                            opt.value = o;
                            opt.textContent = o;
                            sel.appendChild(opt);
                        });
                        sel.value = item.valueText || '';
                        sel.style.fontSize = fontSize;
                        sel.style.textAlign = textAlign;
                        sel.style.textAlignLast = textAlign;
                        if (item.readonly) sel.disabled = true;
                        sel.onchange = e => setAnswer(item, 'value_text', e.target.value);
                        fd.appendChild(sel);
                    } else if (item.type === 'multiline') {
                        const ta = document.createElement('textarea');
                        ta.placeholder = item.placeholder || 'Enter text...';
                        ta.value = item.valueText || '';
                        ta.style.fontSize = Math.max(10, Math.min(boxHeight * 0.3, 15)) + 'px';
                        ta.style.textAlign = textAlign;
                        if (item.readonly) ta.disabled = true;
                        ta.oninput = e => setAnswer(item, 'value_text', e.target.value);
                        fd.appendChild(ta);
                    } else if (item.type === 'checkbox') {
                        fd.title = item.placeholder || 'Check';
                        renderChoice(item, fd);
                        if (!item.readonly) {
                            fd.onclick = () => {
                                setAnswer(item, 'value_bool', !(answers[item.id] || {}).value_bool);
                                renderChoice(item, fd);
                            };
                        }
                    } else if (item.type === 'radio') {
                        fd.title = item.radioOptionValue || 'Select an option';
                        renderChoice(item, fd);
                        if (!item.readonly) {
                            fd.onclick = () => {
                                radioSiblings(item).forEach(sibling => {
                                    answers[sibling.id] = { value_bool: sibling.id === item.id };
                                    const siblingFd = document.getElementById('sign-field-' + sibling.id);
                                    if (siblingFd) renderChoice(sibling, siblingFd);
                                });
                                refreshFields();
                            };
                        }
                    } else if (SIGN_TYPES.includes(item.type)) {
                        fd.classList.add('sig-type');
                        if (item.valueImage) {
                            const img = document.createElement('img');
                            img.src = 'data:image/png;base64,' + item.valueImage;
                            fd.appendChild(img);
                        } else {
                            const btn = document.createElement('button');
                            btn.type = 'button';
                            btn.className = 'field-btn';
                            btn.style.fontSize = Math.max(10, Math.min(boxHeight * 0.4, 15)) + 'px';
                            btn.textContent = item.placeholder || (item.type === 'stamp' ? 'Stamp' : (item.type === 'signature' ? 'Signature' : 'Initials'));
                            fd.appendChild(btn);
                        }
                        if (!item.readonly) {
                            fd.onclick = (e) => {
                                e.stopPropagation();
                                openSigModal(item, fd);
                            };
                            fd.title = item.type === 'stamp' ? 'Click to stamp' : 'Click to sign';
                        }
                    } else if (item.type === 'strikethrough') {
                        fd.classList.add('strike-field');
                        const label = document.createElement('span');
                        label.className = 'strike-label';
                        label.style.fontSize = Math.max(10, Math.min(boxHeight * 0.55, 15)) + 'px';
                        label.textContent = item.placeholder || 'Strikethrough';
                        fd.appendChild(label);
                        const line = document.createElement('div');
                        line.className = 'strike-line';
                        fd.appendChild(line);
                        if (!item.readonly) {
                            fd.title = 'Click to strike through, click again to undo';
                            fd.onclick = () => setAnswer(item, 'value_bool', !(answers[item.id] || {}).value_bool);
                        }
                    }

                    container.appendChild(fd);
                    refreshField(item);
                }

                function refreshField(item) {
                    const fd = document.getElementById('sign-field-' + item.id);
                    if (fd) fd.classList.toggle('completed', isDone(item));
                }

                function refreshFields() {
                    itemsData.forEach(refreshField);
                    updateProgress();
                }

                function setAnswer(item, key, val) {
                    const empty = val === '' || val === null || val === undefined
                        || (val === false && item.type === 'strikethrough');
                    if (empty) {
                        if (answers[item.id]) {
                            delete answers[item.id][key];
                            if (!Object.keys(answers[item.id]).length) delete answers[item.id];
                        }
                    } else {
                        answers[item.id] = Object.assign(answers[item.id] || {}, { [key]: val });
                    }
                    refreshField(item);
                    updateProgress();
                }

                function updateProgress() {
                    const required = requiredItems();
                    const done = required.filter(isDone).length;
                    const pct = required.length ? Math.round((done / required.length) * 100) : 100;
                    document.getElementById('progress-bar').style.width = pct + '%';
                    const progLabel = document.getElementById('progress-label');
                    if (progLabel) {
                        progLabel.textContent = required.length ? done + ' / ' + required.length + ' required fields completed' : '';
                    }
                    updateNavArrow();
                }

                function nextMissingField() {
                    return requiredItems().find(item => !isDone(item));
                }

                // Arrow Navigation
                function updateNavArrow() {
                    const btn = document.getElementById('btn-next-field');
                    if (!btn) return;
                    const nextField = !isSigned && nextMissingField();
                    btn.style.display = nextField ? 'flex' : 'none';
                    btn.style.top = '50%';
                }

                function scrollToNextField() {
                    const nextField = nextMissingField();
                    const fieldEl = nextField && document.getElementById('sign-field-' + nextField.id);
                    if (fieldEl) {
                        fieldEl.scrollIntoView({ behavior: 'smooth', block: 'center' });
                        // Highlight field briefly
                        fieldEl.classList.add('highlight');
                        setTimeout(() => fieldEl.classList.remove('highlight'), 1000);
                    }
                }

                let currentTab = 'auto';
                let currentAutoFont = "'Caveat', cursive";
                let loadedImageBase64 = null;

                function selectSigFont(btn, fontName) {
                    currentAutoFont = fontName;
                    document.querySelectorAll('.sig-font-btn').forEach(b => {
                        b.style.background = '#f8f9fa';
                        b.style.borderColor = '#ccc';
                        b.style.color = '#333';
                    });
                    btn.style.background = '#714B67';
                    btn.style.borderColor = '#714B67';
                    btn.style.color = '#fff';
                    updateAutoSignature();
                }

                function switchTab(t) {
                    currentTab = t;
                    document.querySelectorAll('.sig-tab').forEach(el => el.classList.remove('active'));
                    document.getElementById('tab-' + t).classList.add('active');

                    document.getElementById('wrap-auto').style.display = 'none';
                    document.getElementById('wrap-draw').style.display = 'none';
                    document.getElementById('wrap-load').style.display = 'none';
                    document.getElementById('wrap-' + t).style.display = (t === 'auto') ? 'flex' : 'block';

                    if (t === 'auto') {
                        setTimeout(() => updateAutoSignature(), 30);
                    } else if (t === 'draw') {
                        const canvas = document.getElementById('sig-canvas');
                        if (!signaturePad) {
                            signaturePad = new SignaturePad(canvas, { 
                                backgroundColor: 'rgba(255, 255, 255, 0)',
                                penColor: '#0c2340',
                                minWidth: 1.5,
                                maxWidth: 3.5
                            });
                        }
                        const dpr = window.devicePixelRatio || 1;
                        canvas.width = canvas.parentElement.offsetWidth * dpr;
                        canvas.height = canvas.parentElement.offsetHeight * dpr;
                        canvas.getContext('2d').scale(dpr, dpr);
                        signaturePad.clear();
                    }
                }

                function isStampMode() {
                    return !!currentItem && currentItem.type === 'stamp';
                }

                function initialsOf(name) {
                    return name.split(/\s+/).filter(Boolean).map(word => word[0].toUpperCase() + '.').join('');
                }

                // Company stamp: the lines centred inside a double rounded frame
                function drawStamp(ctx, w, h) {
                    const lines = (document.getElementById('auto-stamp-input').value || '')
                        .split('\n').map(l => l.trim()).filter(Boolean);
                    if (!lines.length) lines.push('Company Name');
                    const color = '#1f3a93';
                    let fontSize = 22;
                    ctx.font = `600 ${fontSize}px Arial, sans-serif`;
                    const widest = Math.max(...lines.map(l => ctx.measureText(l).width));
                    fontSize = Math.max(11, Math.min(fontSize, fontSize * (w - 70) / widest, (h - 40) / (lines.length * 1.35)));
                    const lineHeight = fontSize * 1.35;
                    const boxW = Math.min(w - 10, Math.max(...lines.map(l => {
                        ctx.font = `600 ${fontSize}px Arial, sans-serif`;
                        return ctx.measureText(l).width;
                    })) + 50);
                    const boxH = Math.min(h - 10, lines.length * lineHeight + 30);
                    const x = (w - boxW) / 2;
                    const y = (h - boxH) / 2;

                    ctx.strokeStyle = color;
                    ctx.fillStyle = color;
                    ctx.lineWidth = 3;
                    roundRect(ctx, x, y, boxW, boxH, 12);
                    ctx.lineWidth = 1.2;
                    roundRect(ctx, x + 6, y + 6, boxW - 12, boxH - 12, 8);

                    ctx.textAlign = 'center';
                    ctx.textBaseline = 'middle';
                    const top = h / 2 - ((lines.length - 1) * lineHeight) / 2;
                    lines.forEach((line, index) => {
                        ctx.font = `${index ? 500 : 700} ${index ? fontSize * 0.85 : fontSize}px Arial, sans-serif`;
                        ctx.fillText(index ? line : line.toUpperCase(), w / 2, top + index * lineHeight);
                    });
                }

                function roundRect(ctx, x, y, w, h, r) {
                    ctx.beginPath();
                    ctx.moveTo(x + r, y);
                    ctx.arcTo(x + w, y, x + w, y + h, r);
                    ctx.arcTo(x + w, y + h, x, y + h, r);
                    ctx.arcTo(x, y + h, x, y, r);
                    ctx.arcTo(x, y, x + w, y, r);
                    ctx.closePath();
                    ctx.stroke();
                }

                function updateAutoSignature() {
                    const canvas = document.getElementById('auto-canvas');
                    if (!canvas) return;
                    const ctx = canvas.getContext('2d');

                    const w = canvas.parentElement.offsetWidth || 450;
                    const h = Math.max(120, (canvas.parentElement.offsetHeight || 220) - 85);
                    canvas.width = w;
                    canvas.height = h;

                    ctx.clearRect(0, 0, w, h);
                    if (isStampMode()) {
                        drawStamp(ctx, w, h);
                        return;
                    }
                    const inputVal = (document.getElementById('auto-name-input').value || '').trim();
                    const text = inputVal || 'Signature';

                    let fontSize = 58;
                    if (currentAutoFont.includes('Homemade Apple')) fontSize = 34;
                    else if (currentAutoFont.includes('Sacramento')) fontSize = 62;
                    else if (currentAutoFont.includes('Dancing Script')) fontSize = 54;

                    if (text.length > 20) fontSize = Math.max(22, Math.round(fontSize * 0.6));
                    else if (text.length > 12) fontSize = Math.max(28, Math.round(fontSize * 0.78));

                    ctx.font = `600 ${fontSize}px ${currentAutoFont}`;
                    ctx.fillStyle = "#0c2340";
                    ctx.textAlign = "center";
                    ctx.textBaseline = "middle";
                    ctx.fillText(text, w / 2, h / 2);
                }

                function cropCanvas(sourceCanvas) {
                    const ctx = sourceCanvas.getContext('2d');
                    const w = sourceCanvas.width;
                    const h = sourceCanvas.height;
                    if (!w || !h) return sourceCanvas;

                    try {
                        const imgData = ctx.getImageData(0, 0, w, h);
                        const data = imgData.data;
                        let minX = w, minY = h, maxX = -1, maxY = -1;

                        for (let y = 0; y < h; y++) {
                            for (let x = 0; x < w; x++) {
                                const alpha = data[((y * w) + x) * 4 + 3];
                                if (alpha > 15) {
                                    if (x < minX) minX = x;
                                    if (x > maxX) maxX = x;
                                    if (y < minY) minY = y;
                                    if (y > maxY) maxY = y;
                                }
                            }
                        }

                        if (maxX < minX || maxY < minY) {
                            return sourceCanvas;
                        }

                        const pad = 6;
                        const cropX = Math.max(0, minX - pad);
                        const cropY = Math.max(0, minY - pad);
                        const cropW = Math.min(w - cropX, (maxX - minX) + (pad * 2));
                        const cropH = Math.min(h - cropY, (maxY - minY) + (pad * 2));

                        const cropped = document.createElement('canvas');
                        cropped.width = cropW;
                        cropped.height = cropH;
                        const cropCtx = cropped.getContext('2d');
                        cropCtx.drawImage(sourceCanvas, cropX, cropY, cropW, cropH, 0, 0, cropW, cropH);
                        return cropped;
                    } catch (e) {
                        return sourceCanvas;
                    }
                }

                function handleSignatureUpload(e) {
                    const file = e.target.files[0];
                    if (!file) return;
                    const reader = new FileReader();
                    reader.onload = function(event) {
                        loadedImageBase64 = event.target.result;
                        const preview = document.getElementById('load-preview');
                        preview.src = loadedImageBase64;
                        preview.style.display = 'block';
                    };
                    reader.readAsDataURL(file);
                }

                // Signature modal
                let typedSignerName = (document.getElementById('auto-name-input').value || '').trim();
                document.getElementById('auto-name-input').addEventListener('input', function() {
                    if (currentItem && currentItem.type === 'signature') typedSignerName = this.value.trim();
                });

                function openSigModal(item, fd) {
                    currentItem = item;
                    currentFieldDiv = fd;
                    const titles = { signature: 'Sign Document', stamp: 'Stamp Document' };
                    document.getElementById('sig-modal-title').textContent = titles[item.type] || 'Initial Document';
                    const stamp = item.type === 'stamp';
                    document.getElementById('auto-name-input').style.display = stamp ? 'none' : '';
                    document.getElementById('auto-font-row').style.display = stamp ? 'none' : 'flex';
                    document.getElementById('auto-stamp-input').style.display = stamp ? '' : 'none';
                    if (!stamp) {
                        document.getElementById('auto-name-input').value =
                            item.type === 'signature' ? typedSignerName : initialsOf(typedSignerName);
                    }
                    document.getElementById('sig-modal-overlay').classList.add('show');

                    switchTab('auto');
                    setTimeout(() => updateAutoSignature(), 50);
                }

                function closeSigModal() { document.getElementById('sig-modal-overlay').classList.remove('show'); }

                function clearSig() {
                    if (currentTab === 'draw' && signaturePad) {
                        signaturePad.clear();
                    } else if (currentTab === 'auto') {
                        document.getElementById(isStampMode() ? 'auto-stamp-input' : 'auto-name-input').value = '';
                        updateAutoSignature();
                    } else if (currentTab === 'load') {
                        document.getElementById('load-file-input').value = '';
                        document.getElementById('load-preview').style.display = 'none';
                        loadedImageBase64 = null;
                    }
                }

                function getSignatureBase64() {
                    if (currentTab === 'draw') {
                        if (!signaturePad || signaturePad.isEmpty()) return null;
                        const canvas = document.getElementById('sig-canvas');
                        const cropped = cropCanvas(canvas);
                        return cropped.toDataURL('image/png');
                    } else if (currentTab === 'auto') {
                        const inputId = isStampMode() ? 'auto-stamp-input' : 'auto-name-input';
                        const input = (document.getElementById(inputId).value || '').trim();
                        if (!input) return null;
                        const canvas = document.getElementById('auto-canvas');
                        const cropped = cropCanvas(canvas);
                        return cropped.toDataURL('image/png');
                    } else if (currentTab === 'load') {
                        return loadedImageBase64;
                    }
                    return null;
                }

                function renderCompletedSig(targetFd, dataUrl) {
                    targetFd.innerHTML = '';
                    const img = document.createElement('img');
                    img.src = dataUrl;
                    targetFd.appendChild(img);
                    targetFd.title = 'Click to edit';
                }

                function saveSig(signAll = false) {
                    const dataUrl = getSignatureBase64();
                    if (!dataUrl) {
                        alert(isStampMode() ? 'Please provide a stamp first.' : 'Please provide a signature first.');
                        return;
                    }

                    const base64 = dataUrl.split(',')[1];
                    const targets = [currentItem];
                    if (signAll) {
                        // Same answer for every other field of this kind still empty
                        itemsData.forEach(item => {
                            if (item.type === currentItem.type && item.id !== currentItem.id && !item.readonly && !isDone(item)) {
                                targets.push(item);
                            }
                        });
                    }
                    targets.forEach(item => {
                        const fd = document.getElementById('sign-field-' + item.id);
                        if (fd) {
                            renderCompletedSig(fd, dataUrl);
                            setAnswer(item, 'value_image', base64);
                        }
                    });

                    closeSigModal();
                }

                // Submit
                document.getElementById('btn-complete') && document.getElementById('btn-complete').addEventListener('click', async function() {
                    const missing = requiredItems().filter(item => !isDone(item));
                    if (missing.length) {
                        alert('Please fill the ' + missing.length + ' required field(s) left before signing.');
                        scrollToNextField();
                        return;
                    }
                    // Extension hook: other modules may ask for more information
                    // (resolve to extra request parameters, or to null to cancel)
                    const extraParams = window.signBeforeSubmit ? await window.signBeforeSubmit() : {};
                    if (!extraParams) {
                        return;
                    }

                    this.disabled = true;
                    this.textContent = 'Submitting…';

                    fetch('/my/dms/signature/' + reqId + '/accept', {
                        method: 'POST',
                        headers: { 'Content-Type': 'application/json' },
                        body: JSON.stringify({ params: Object.assign({ items_data: answers, access_token: accessToken || null }, extraParams) })
                    }).then(r => r.json()).then(data => {
                        if (data.result && data.result.error) {
                            alert(data.result.error);
                            this.disabled = false;
                            this.textContent = 'Complete & Sign';
                        } else {
                            if (data.result && data.result.next_signer_url) {
                                document.getElementById('nextSignerName').textContent = data.result.next_signer_name;
                                document.getElementById('nextSignerBtnName').textContent = data.result.next_signer_name;
                                document.getElementById('btnNextSigner').onclick = function() {
                                    window.location.href = data.result.next_signer_url;
                                };
                                const modal = new bootstrap.Modal(document.getElementById('nextSignerModal'));
                                modal.show();
                            } else {
                                document.querySelector('.actions').innerHTML = '✓ Signed Successfully';
                                document.getElementById('progress-bar').style.width = '100%';
                                const targetUrl = (data.result && data.result.redirect_url) || '/my/dms/signatures';
                                setTimeout(() => {
                                    window.location.replace(targetUrl);
                                }, 1200);
                            }
                        }
                    }).catch(() => {
                        this.disabled = false;
                        this.textContent = 'Complete & Sign';
                        alert('An error occurred. Please try again.');
                    });
                });

                updateProgress();

                if (document.fonts && document.fonts.ready) {
                    document.fonts.ready.then(function() {
                        if (currentTab === 'auto') {
                            updateAutoSignature();
                        }
                    });
                }
